func TestSelectReviewAgent_OverrideResolvesSpecificAgent(t *testing.T) {
	t.Parallel()
	review := map[string]settings.ReviewConfig{
		testAgentName:  {Skills: []string{"/a"}},
		testCodexAgent: {Skills: []string{"/b"}},
	}

